Dictionary = {}
Dictionary.__index = Dictionary

--传入类名字符串即可
function Dictionary:New(tk, tv)
    local o = {keyType = tk, valueType = tv}
    setmetatable(o, self)
    o.keyList = {}
    return o
end

function Dictionary:Add(key, value)
    if self[key] == nil then
        self[key] = value
        table.insert(self.keyList, key)
    else
        self[key] = value
    end
end

---cww: ForEachValue有一个问题：在此方法的active方法中返回一个值无法被外界接收，
---因为active是一个function，闭包时的返回值只是作为了ForEachValue的参数传入ForEachValue之中
---此问题后续修复，临时解决方案是使用一个临时变量接收需要返回的值，待遍历结束后将之返回
function Dictionary:ForEachValue(action)
    local count = self:Count()
    for i=count,1,-1 do
        local value = self[self.keyList[i]];
        action(value);
    end
end

--从当前字典中找出指定起始位置和个数的一个子字典
function Dictionary:FindChildDic(start,count)
    local curDicCount = self:Count();

    if start > curDicCount then
        logError("需要查找的部分已经超出当前字典的总范围");
        return;
    end
    local endIndex = (start + count) - 1;
    if endIndex > curDicCount then
        endIndex = curDicCount;
    end

    local temp = Dictionary:New();

    for i = start, endIndex do
        local key = self.keyList[i]
        local value = self[self.keyList[i]];
        temp:Add(key,value);
    end

    return temp;
end

function Dictionary:Clear()
    local count = self:Count()
    for i=count,1,-1 do
        self[self.keyList[i]] = nil
        table.remove(self.keyList)
    end
end

function Dictionary:Destroy()
    self:Clear();
    self.keyList = nil;
    self = nil;
end

function Dictionary:ContainsKey(key)
    local count = self:Count()
    for i=1,count do
        if self.keyList[i] == key then
            return true
        end
    end
    return false
end

function Dictionary:ContainsValue(value)
    local count = self:Count()
    for i=1,count do
        if self[self.keyList[i]] == value then
            return true
        end
    end
    return false
end

function Dictionary:Count()
    return table.getn(self.keyList)
end

function Dictionary:Iter()
    local i = 0
    local n = self:Count()
    return function ()
        i = i + 1
        if i <= n then
            return self.keyList[i]
        end
        return nil
    end
end

function Dictionary:Remove(key)
    if self:ContainsKey(key) then
        local count = self:Count()
        for i=1,count do
            if self.keyList[i] == key then
                table.remove(self.keyList, i)
                break
            end
        end
        self[key] = nil
    end
end

function Dictionary:ForEach(action)
    local count = self:Count()
    for i=1,count do
        local key = self.keyList[i];
        local value = self[key];
        action(value);
    end
end

function Dictionary:ForEachAndIndex(action)
    local count = self:Count()
    for i=1,count do
        local key = self.keyList[i];
        local value = self[key];
        action(value,i);
    end
end

function Dictionary:ForEachAndKey(action)
    local count = self:Count()
    for i=1,count do
        local key = self.keyList[i];
        local value = self[key];
        action(value,key);
    end
end

--将数据按照指定字段重新排序
function Dictionary:RefreshDic(type)
    local count = self:Count()
    local valueTable = {}
    for i=1,count do
        local key = self.keyList[i];
        local value = self[key];
        valueTable[i] = value;
    end
    self:Clear();
    for j=1,#valueTable do
        if type == "id" then
            valueTable[j].id = j;
            self:Add(j,valueTable[j]);
        elseif type == "index" then
            valueTable[j].index = j;
            self:Add(valueTable[j].id,valueTable[j]);
        end
    end
end


function Dictionary:Reset()
    local count = self:Count()
    local valueTable = {}
    for i=1,count do
        local key = self.keyList[i];
        local value = self[key];
        valueTable[i] = value;
    end
    self:Clear();
    for j=1,#valueTable do
        self:Add(j,valueTable[j]);
    end
end

function Dictionary:KeyType()
    return self.keyType
end

function Dictionary:ValueType()
    return self.valueType
end

